#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-or-later
"""Package the exact original Bravura default cue oval bank; no primary-file writes."""
import argparse,hashlib,json,platform,subprocess,zipfile,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
JAR_SHA='9b35257edea808ec80a8bcd48882d174b107152d9640b5ca33e1365593cff2a5'
COMMIT='9e1e55cd2746037d059345881c53e6a6754bffbd'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def digest(b):return hashlib.sha256(b).hexdigest()
def dump(p,v):p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--oracle-home',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--observer',type=Path);a=p.parse_args()
 assert platform.system()=='Linux';dist=a.oracle_home/'official/opt/audiveris/lib';jar=dist/'app/audiveris.jar';assert sha(jar)==JAR_SHA
 javac=a.oracle_home/'jdk-21.0.12.1+1/bin/javac';java=dist/'runtime/bin/java';observer=a.observer or ROOT/'scripts/java/CueHeadFontBankOracle.java'
 a.output.mkdir(parents=True,exist_ok=False);classes=a.output/'classes';classes.mkdir();snapshot=a.output/'CueHeadFontBankOracle.java';shutil.copyfile(observer,snapshot)
 compile_cmd=[str(javac),'--release','21','-d',str(classes),str(snapshot)];subprocess.run(compile_cmd,check=True)
 folder=a.output/'Bravura';folder.mkdir();home=a.output/'home';home.mkdir();tmp=a.output/'tmp';tmp.mkdir()
 command=[str(java),'-Djava.awt.headless=true','-Duser.home='+str(home),'-Djava.io.tmpdir='+str(tmp),'-cp',str(dist/'app/*')+':'+str(classes),'CueHeadFontBankOracle',str(folder),'Bravura']
 with (a.output/'original.log').open('w') as log:subprocess.run(command,check=True,stdout=log,stderr=subprocess.STDOUT,timeout=120)
 data=json.loads((folder/'assets.json').read_text());cal=json.loads((folder/'calibration.json').read_text());assert data['family']=='Bravura' and len(data['assets'])==8
 templates=[{'key':{'shape':x['shape'],'point_size':x['point_size']},'width':x['width'],'height':x['height'],'fat_bounds':[int(v) for v in x['fat_bounds']],'slim_bounds':[int(v) for v in x['slim_bounds']],'anchors':x['anchors'],'points':[{'x':v[0],'y':v[1],'d':v[2]} for v in x['points']]} for x in data['assets']]
 payload=(json.dumps({'schema':1,'templates':templates,'calibration':cal},separators=(',',':'),allow_nan=False)+'\n').encode()
 with zipfile.ZipFile(jar) as z:fontsha=digest(z.read('res/Bravura.otf'));modelsha=digest(z.read('res/basic-classifier.zip'))
 assert fontsha=='dca2d90c88437a701b1c2e71fa54e76f9fa41d7deee935d74dc871ea66ecfdd2'
 coverage=(json.dumps({'family':'Bravura','point_sizes':[28,44],'shapes':['BREVE','WHOLE_NOTE','NOTEHEAD_VOID','NOTEHEAD_BLACK']},sort_keys=True)+'\n').encode()
 manifest={'schema':1,'bank_id':'audiveris-5.11.0-bravura-default-cue-v1','upstream_version':'5.11.0','upstream_commit':COMMIT,'font_family':'Bravura','font_version':'1.392','font_sha256':fontsha,'model_name':'basic-classifier.zip','model_sha256':modelsha,'coverage_input_sha256':digest(coverage),'generator':'CueHeadFontBankOracle; unmodified official 5.11 JAR; '+data['java']+'; '+data['os']+'; default TemplateFactory constants','asset_sha256':digest(payload),'keys':[x['key'] for x in templates],'calibration_sizes':[x['point_size'] for x in cal]}
 package=a.output/'packaged';package.mkdir();dump(package/'manifest.json',manifest);(package/'templates.json').write_bytes(payload)
 identity={'manifest_sha256':sha(package/'manifest.json'),'upstream_commit':COMMIT,'font_sha256':fontsha,'model_sha256':modelsha,'coverage_input_sha256':digest(coverage)}
 trust='Trust { '+', '.join(k+': "'+v+'"' for k,v in identity.items())+' }'
 (package/'cue_identity.rs').write_text('// SPDX-License-Identifier: AGPL-3.0-or-later\n// Generated by build_cue_head_bank.py from the original default cue sizes.\nimpl Bank {\n    pub fn load_cue_default() -> Result<Self, Error> {\n        Self::from_bytes(include_bytes!("../assets/cue-default/manifest.json"), include_bytes!("../assets/cue-default/templates.json"), '+trust+')\n    }\n}\n')
 dump(a.output/'provenance.json',{'status':'passed','native_outputs_used':False,'jar_sha256':JAR_SHA,'upstream_commit':COMMIT,'observer_source_sha256':{'scripts/java/CueHeadFontBankOracle.java':sha(snapshot)},'compiler_executable_sha256':sha(javac),'runtime_executable_sha256':sha(java),'font_sha256':fontsha,'model_sha256':modelsha,'compile_command':compile_cmd,'command':command,'original_files_sha256':{str(x.relative_to(folder)):sha(x) for x in sorted(folder.iterdir())},'packaged_files_sha256':{x.name:sha(x) for x in sorted(package.iterdir())},'point_sizes':[28,44],'templates':8})
if __name__=='__main__':main()
